import{_ as i,o,c as a,ak as e}from"./chunks/framework.Bxj7Kmuk.js";const r="/projects/AiHand/en/latest/assets/image2.B7y-zdjZ.webp",n="/projects/AiHand/en/latest/assets/image3.DOjcp8hq.webp",s="/projects/AiHand/en/latest/assets/image4.UV8t5oy0.webp",l="/projects/AiHand/en/latest/assets/image5.ChbQm69m.webp",c="/projects/AiHand/en/latest/assets/image6.CFp1qU1K.webp",d="/projects/AiHand/en/latest/assets/image7.BMZCwePA.webp",m="/projects/AiHand/en/latest/assets/image8.CGslOVww.webp",p="/projects/AiHand/en/latest/assets/image9.xKVVxLkp.webp",h="/projects/AiHand/en/latest/assets/image10.CrkT-ifa.webp",P=JSON.parse('{"title":"2. Introduction to micro:bit and Expansion Board","description":"","frontmatter":{},"headers":[],"relativePath":"docs/2.Introduction_to_microbitand_Expansion_Board.md","filePath":"docs/2.Introduction_to_microbitand_Expansion_Board.md"}'),u={name:"docs/2.Introduction_to_microbitand_Expansion_Board.md"};function g(_,t,b,f,x,w){return o(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="_2-introduction-to-micro-bit-and-expansion-board" tabindex="-1">2. Introduction to micro:bit and Expansion Board <a class="header-anchor" href="#_2-introduction-to-micro-bit-and-expansion-board" aria-label="Permalink to &quot;2. Introduction to micro:bit and Expansion Board&quot;">​</a></h1><h2 id="_2-1-micro-bit" tabindex="-1">2.1 micro:bit <a class="header-anchor" href="#_2-1-micro-bit" aria-label="Permalink to &quot;2.1 micro:bit&quot;">​</a></h2><h3 id="_2-1-1-introduction" tabindex="-1">2.1.1 Introduction <a class="header-anchor" href="#_2-1-1-introduction" aria-label="Permalink to &quot;2.1.1 Introduction&quot;">​</a></h3><p style="text-align:center;"><img loading="lazy" height="350" width="501" src="'+r+'" style="width:420px;"><img loading="lazy" height="350" width="501" src="'+n+'" style="width:420px;"></p><p>micro:bit is a microcontroller designed for programming education for adolescents. Being led by BBC, it is jointly developed by Microsoft, Samsung, ARM and other partners.</p><p>The size of micro:bit merely accounts for half of the bank card. Although the size is small, many rich functional electronic modules have been well equipped on it, including Bluetooth, an accelerometer, an electronic compass, three buttons, a 5x5 LED dot matric, and a microphone.</p><p>Micro:bit features numerous open-source libraries and interesting solutions, which can be accessed on the website:<a href="https://makecode.microbit.org/" target="_blank" rel="noreferrer">https://makecode.microbit.org/</a></p><img loading="lazy" height="757" width="1268" class="common_img" src="'+s+'"><h3 id="_2-1-2-parameter" tabindex="-1">2.1.2 Parameter <a class="header-anchor" href="#_2-1-2-parameter" aria-label="Permalink to &quot;2.1.2 Parameter&quot;">​</a></h3><ul><li><p>Processor: Nordic nRF52833</p></li><li><p>ARM: Cortex-M4 32-bit+FPU 64MHz</p></li><li><p>Memory/Flash: 128KB RAM/512KB Flash</p></li><li><p>Wireless: 2.4GHz Micro:bit Radio/BLE BT 5.0</p></li><li><p>Power: 5V powered through Micro USB port, 3V powered through edge connector or battery pack</p></li><li><p>Working current: 300mA</p></li><li><p>Dimension: 52*43.2mm</p></li></ul><h3 id="_2-1-3-function-diagram" tabindex="-1">2.1.3 Function Diagram <a class="header-anchor" href="#_2-1-3-function-diagram" aria-label="Permalink to &quot;2.1.3 Function Diagram&quot;">​</a></h3><p>As shown below, micro:bit is mainly composed of built-in modules, such as an accelerometer, programmable buttons, pins, LED dot matrix, USB, Bluetooth, radio, and electronic compass.</p><img loading="lazy" height="184" width="434" class="common_img" src="'+l+'" style="width:700px;"><img loading="lazy" height="221" width="390" class="common_img" src="'+c+'" style="width:700px;"><h3 id="_2-1-4-module-function" tabindex="-1">2.1.4 Module Function <a class="header-anchor" href="#_2-1-4-module-function" aria-label="Permalink to &quot;2.1.4 Module Function&quot;">​</a></h3><ul><li><p>Built-in speaker</p></li><li><p>MEMS microphone with LED indicator</p></li><li><p>Touch-sensitive logo</p></li><li><p>Built-in sleep or shutdown mode allows you to turn off the circuit power without removing the battery</p></li><li><p>Discrete voltage regulator can provide up to 200mA of current to peripherals</p></li><li><p>Edge connector for connecting alligator clips and wires</p></li></ul><h3 id="_2-1-5-pin-output" tabindex="-1">2.1.5 Pin Output <a class="header-anchor" href="#_2-1-5-pin-output" aria-label="Permalink to &quot;2.1.5 Pin Output&quot;">​</a></h3><img loading="lazy" height="826" width="953" class="common_img" src="'+d+'"><h2 id="_2-2-micro-bit-expansion-board" tabindex="-1">2.2 micro:bit Expansion Board <a class="header-anchor" href="#_2-2-micro-bit-expansion-board" aria-label="Permalink to &quot;2.2 micro:bit Expansion Board&quot;">​</a></h2><img loading="lazy" height="658" width="959" class="common_img" src="'+m+'" style="width:600px;"><h3 id="_2-2-1-introduction" tabindex="-1">2.2.1 Introduction <a class="header-anchor" href="#_2-2-1-introduction" aria-label="Permalink to &quot;2.2.1 Introduction&quot;">​</a></h3><p>The micro:bit expansion board is specially designed to facilitate the usage of micro:bit. It not only brings out the pins of micro:bit, but also adds different sensors and controllable components.</p><p>The micro:bit expansion board integrates two RGB lights, a buzzer, a sound sensor, six servo control ports, two DC motor interfaces, and six expansion ports.</p><h3 id="_2-2-2-parameter" tabindex="-1">2.2.2 Parameter <a class="header-anchor" href="#_2-2-2-parameter" aria-label="Permalink to &quot;2.2.2 Parameter&quot;">​</a></h3><ul><li><p>Compatible with micro:bit</p></li><li><p>Power input: 5V (USB power input) / 7.4V (DC power input)</p></li><li><p>Dimension: 83*60mm</p></li></ul><h3 id="_2-2-3-function-diagram" tabindex="-1">2.2.3 Function Diagram <a class="header-anchor" href="#_2-2-3-function-diagram" aria-label="Permalink to &quot;2.2.3 Function Diagram&quot;">​</a></h3><img loading="lazy" height="1022" width="1323" class="common_img" src="'+p+'"><table class="docutils-nobg" border="1"><tr><td>1.RGB light module</td><td>2.Serial communication interface</td></tr><tr><td>3.micro:bit socket</td><td>4.I2C interface</td></tr><tr><td>5.Power output interface</td><td>6.Motor interface</td></tr><tr><td>7.PWM servo interface</td><td>8.Power switch</td></tr><tr><td>9.DC power interface</td><td>10.IO interface</td></tr></table><h3 id="_2-2-4-installation-diagram" tabindex="-1">2.2.4 Installation Diagram <a class="header-anchor" href="#_2-2-4-installation-diagram" aria-label="Permalink to &quot;2.2.4 Installation Diagram&quot;">​</a></h3><p>The installation method for the micro:bit is shown below:</p><img loading="lazy" height="969" width="866" class="common_img" src="'+h+'" style="width:600px;">',31)])])}const B=i(u,[["render",g]]);export{P as __pageData,B as default};
